/* Old shell=v2 presentation. Bindings belong to the package's PDL. */
'use strict';

/* MissionControlPage import buttons, MemberListPage and MemoryNavigation. */
PDL_COMPONENTS.v2SettingsButton = function (p,sc,root) {
  const q=pvDeep(p,root,sc), styles={member:'member-button',return:'whitespace-nowrap rounded-lg px-2 py-2 text-compact text-cafe-muted hover:bg-cafe-surface-sunken',text:'text-xs text-cafe-accent underline'};
  const cls=styles[q.role] || 'inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium shadow-[0_1px_3px_rgba(43,33,26,0.06)] transition-colors disabled:opacity-40 ' + (q.primary?'bg-cafe-accent text-[var(--cafe-surface)]':'bg-[var(--console-card-bg)] text-cafe-secondary hover:bg-[var(--console-hover-bg)]');
  return '<button type="'+(q.submit?'submit':'button')+'" class="'+cls+'"'+actAttrs(q.act,q.args)+(q.disabled?' disabled':'')+'>'+h(q.label)+'</button>';
};
/* MemoryPagePreview's page tabs and MemoryNav / SignalNav's underlined route tabs. */
PDL_COMPONENTS.v2PageTabs=function(p,sc,root){const q=pvDeep(p,root,sc),line=q.role==='catalog'||q.role==='signals',family=q.role==='family';return '<nav class="'+(line?'flex console-divider-b':'flex max-w-full gap-1 overflow-x-auto')+'" aria-label="'+h(q.label||tc("v2f.copy.w003"))+'">'+q.options.map(function(x){const selected=x.v===q.value,c=q.counts&&q.counts.find(function(c){return c.v===x.v;});return '<button type="button" class="'+(line?'inline-flex items-center px-5 py-2.5 text-sm font-semibold transition-colors '+(selected?'border-b-2 border-[var(--console-button-emphasis)] text-[var(--console-button-emphasis)]':'text-cafe-muted hover:text-cafe-secondary'):family?'shell-focusable rounded-lg border px-3 py-2 '+(selected?'border-cafe-subtle bg-cafe-surface-sunken font-medium':'border-transparent text-cafe-muted'):'whitespace-nowrap rounded-lg px-3 py-2 text-sm '+(selected?'bg-cafe-surface-sunken font-medium':'text-cafe-muted'))+'"'+actAttrs(q.act,Object.assign({},q.args,{v:x.v}))+(selected?' aria-current="page"':'')+'>'+h(x.label)+(c&&['taste','profile'].includes(x.v)?' '+h(c.count):'')+'</button>';}).join('')+'</nav>';};
PDL_COMPONENTS.v2MemoryTitle=function(){return ("<span class=\"text-base font-medium\">"+h(tc("v2f.copy.w004"))+"</span>");};
PDL_COMPONENTS.v2MemoryPage=function(p,sc,root){
  if(pvOk(p.catalog,sc,root))return pvBlocks(p.blocks,sc,root);
  return '<div class="v2-memory-page flex h-full min-h-0 flex-col bg-[var(--console-shell-bg)] text-cafe" data-testid="memory-page-preview"><header class="flex flex-wrap items-center gap-3 border-b border-cafe-subtle px-4 py-3 md:px-8">'+pvBlocks(p.header,sc,root)+'</header><main class="min-h-0 flex-1 overflow-y-auto p-4 md:p-8">'+pvBlocks(p.blocks,sc,root)+'</main></div>';
};
/* memory/page/MemorySearch.tsx — the original input and its separate submit icon. */
PDL_COMPONENTS.v2MemorySearch=function(p,sc,root){const q=pvDeep(p,root,sc);return '<form class="flex items-center gap-2 md:ml-auto" data-form="'+h(q.form)+'"><input class="w-60 rounded-lg border border-cafe-subtle bg-[var(--console-card-bg)] px-3 py-2 text-sm" id="'+h(q.id)+'" data-input="'+h(q.input)+'" value="'+h(q.value)+'" placeholder="'+h(q.label)+'" aria-label="'+h(q.label)+("\"><button type=\"submit\" class=\"rounded-lg p-2 text-cafe-muted\" aria-label=\""+h(tc("v2f.copy.w005"))+"\">")+v2Glyph('search')+'</button></form>';};
/* memory/page/MemoryTasteSky.tsx — unchanged background and six constellation assets. */
PDL_COMPONENTS.v2MemoryTasteSky=function(p,sc,root){const q=pvDeep(p,root,sc);return '<section class="relative -mx-4 -mt-4 bg-cover bg-center md:-mx-8 md:-mt-8 '+(q.expanded?'h-72':'h-16')+'" style="background-image:url(\''+h(asset(q.expanded?'v2-memory-dome-hero':'v2-memory-dome-strip'))+'\')" data-testid="taste-dome" data-expanded="'+q.expanded+("\" aria-label=\""+h(tc("v2f.copy.w006"))+"\"><div class=\"absolute inset-x-0 top-0 flex items-center justify-between gap-3 p-4 text-[var(--cafe-image-foreground)] md:px-8\"><h1 class=\"text-display-sm font-serif\">"+h(tc("v2f.copy.w006"))+"</h1><button type=\"button\" class=\"rounded-lg border border-[var(--cafe-image-foreground)] px-3 py-1 text-compact\"")+actAttrs(q.toggle.act,q.toggle.args)+'>'+(q.expanded?tc("v2f.copy.w007"):tc("v2f.copy.w008"))+'</button></div>'+(q.expanded?'<div class="absolute inset-x-4 top-16 grid grid-cols-6 gap-2 text-center text-[var(--cafe-image-foreground)] md:inset-x-32 md:gap-6">'+q.families.map(function(x){const c=q.counts.find(function(c){return c.v===x.id;});return '<button type="button" aria-label="'+h(x.label)+(tc("v2f.copy.w009")+'"')+(x.disabled?' disabled class="opacity-70"':actAttrs(x.act,x.args))+'><img src="'+h(asset(x.asset))+'" alt="" width="80" height="80" class="mx-auto object-contain '+(x.id==='taste'?'h-16 w-16':'h-12 w-12')+'"><p class="mt-1 text-compact">'+h(x.label)+'</p><p class="text-xs">'+h(x.id==='taste'?c.count+" "+tc("v2f.copy.w010"):x.summary)+'</p></button>';}).join('')+'</div>':'')+'</section>';};
PDL_COMPONENTS.v2MemoryFamilyBar=function(p,sc,root){return '<div class="my-5 flex flex-wrap items-center gap-2 text-compact">'+pvBlocks(p.blocks,sc,root)+'</div>';};
PDL_COMPONENTS.v2MeetingDisconnected=function(){return ("<span class=\"rounded-lg border border-dashed border-cafe-subtle px-2 py-1 text-xs text-cafe-muted\">"+h(tc("v2f.copy.w011"))+"</span>");};
PDL_COMPONENTS.v2MemoryCandidateHint=function(){return ("<span class=\"text-xs text-cafe-muted\">"+h(tc("v2f.copy.w012"))+"</span>");};
PDL_COMPONENTS.v2MemorySort=function(p,sc,root){const q=pvDeep(p,root,sc);return ("<select id=\"mem-sort\" data-change=\"cafeSel\" aria-label=\""+h(tc("v2f.copy.w013"))+"\" class=\"ml-auto rounded-lg border border-cafe-subtle bg-[var(--console-card-bg)] px-3 py-2 text-compact\"><option value=\"recent\"")+(q.value==='recent'?' selected':'')+(">"+h(tc("v2f.copy.w014"))+"</option><option value=\"hits\"")+(q.value==='hits'?' selected':'')+(">"+h(tc("v2f.copy.w015"))+"</option></select>");};
/* memory/page/MemoryReadState.tsx. */
PDL_COMPONENTS.v2MemoryReadState=function(p,sc,root){const q=pvDeep(p,root,sc);if(q.load!=='loading'&&q.load!=='error'&&!pvOk(p.empty,sc,root))return '';return '<div role="'+(q.load==='error'?'alert':'status')+'" class="rounded-lg border border-cafe-subtle bg-[var(--console-card-bg)] p-4 text-sm text-cafe-muted">'+h(q.load==='loading'?tc("v2f.copy.w016")+q.noun+'…':q.load==='error'?tc("v2f.copy.w017")+q.noun:tc("v2f.copy.w018")+q.noun)+(q.load==='error'?'<button type="button" class="ml-3 text-cafe-accent underline"'+actAttrs(q.refresh.act,q.refresh.args)+(">"+h(tc("v2f.copy.w019"))+"</button>"):'')+'</div>';};
PDL_COMPONENTS.v2MemoryCards=function(p,sc,root){return '<div class="grid items-start gap-4 lg:grid-cols-2">'+pvBlocks(p.blocks,sc,root)+'</div>';};
/* MemoryTasteCard: the app supplies the original record, never screenshot content. */
PDL_COMPONENTS.v2MemoryTasteCard=function(p,sc,root){const q=pvDeep(p,root,sc),x=q.record,candidate=x.takeawayCandidate&&x.takeawayCandidate.basedOnRevision===x.revision?x.takeawayCandidate:null;return '<article class="rounded-xl border bg-[var(--console-card-bg)] p-4 '+(q.selected?'border-cafe-accent':'border-cafe-subtle')+'" data-testid="taste-card" data-memory-id="'+h(x.id)+'"><button type="button" class="w-full text-left"'+actAttrs(q.act,q.args)+'><span class="mb-2 block text-xs text-cafe-muted">'+(candidate?tc("v2f.copy.w020"):x.takeaway?tc("v2f.copy.w021"):tc("v2f.copy.w022"))+'</span><p class="line-clamp-3 break-words text-sm">'+h(candidate?candidate.takeaway:x.takeaway||x.quotes[0]||x.title)+'</p><p class="mt-2 line-clamp-2 break-words text-compact text-cafe-muted">'+h(x.takeaway?x.quotes[0]||tc("v2f.copy.w023"):tc("v2f.copy.w024")+x.scene)+'</p><div class="mt-3 flex flex-wrap items-center gap-2 text-xs text-cafe-muted">'+(x.catId?v2Avatar(x.catId,20)+h(whoInfo(x.catId).name):tc("v2f.copy.w025"))+'<time>'+h(x.approval&&x.approval.status==='approved'?v2MemoryDate(x.approval.proposedAt):tc("v2f.copy.w026")+" "+v2MemoryDate(x.when)+" "+tc("v2f.copy.w027")+(x.approval&&x.approval.status==='unavailable'?tc("v2f.copy.w017"):tc("v2f.copy.w028")))+'</time><span>'+h(x.dimension)+'</span>'+(x.visibility==='private'?("<span>"+h(tc("v2f.copy.w029"))+"</span>"):'')+'</div>'+(x.pendingCorrectionCount>0?'<p class="mt-2 text-compact text-cafe-muted">'+x.pendingCorrectionCount+(" "+h(tc("v2f.copy.w030"))+"</p>"):'')+'<p class="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-xs text-cafe-muted">'+(x.recall===null?tc("v2f.copy.w031"):(x.recall&&x.recall.search&&x.recall.search.hits?("<span class=\"whitespace-nowrap\">"+h(tc("v2f.copy.w032"))+" ")+x.recall.search.hits+(" "+h(tc("v2f.copy.w033"))+"</span>"):'')+(x.recall&&x.recall.namedDelivery&&x.recall.namedDelivery.counts.presented?("<span class=\"whitespace-nowrap\">"+h(tc("v2f.copy.w034"))+" ")+x.recall.namedDelivery.counts.presented+(" "+h(tc("v2f.copy.w033"))+"</span>"):''))+'</p></button></article>';};
/* The other families keep their separate old component identities. */
PDL_COMPONENTS.v2MemoryProfileCard=function(p,sc,root){const q=pvDeep(p,root,sc),x=q.record;return '<article class="rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4"><button class="w-full text-left"'+actAttrs(q.act,q.args)+'><div class="flex items-start justify-between gap-3"><h2 class="font-medium text-sm">'+h(x.title)+'</h2><span class="text-xs text-cafe-muted">'+h(x.layer)+'</span></div><div class="mt-3 whitespace-pre-wrap text-compact text-cafe-muted">'+h(x.content)+'</div></button></article>';};
PDL_COMPONENTS.v2MemoryPersonCard=function(p,sc,root){const q=pvDeep(p,root,sc),x=q.record;return '<article class="rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4"><button type="button" class="text-left text-base font-medium" aria-pressed="'+!!q.selected+'"'+actAttrs(q.act,q.args)+'>'+h(x.displayName)+'</button><p class="mt-2 text-compact text-cafe-muted">'+h(x.currentClaimCount)+" "+tc("v2f.copy.w035")+" "+h(x.activeInteractionCount)+(" "+h(tc("v2f.copy.w036"))+"</p><p class=\"mt-2 text-xs text-cafe-muted\">")+h(v2MemoryDate(x.updatedAt))+(" "+h(tc("v2f.copy.w037"))+"</p></article>");};
PDL_COMPONENTS.v2MemoryEntityCard=function(p,sc,root){const q=pvDeep(p,root,sc),x=q.record;return '<article class="rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4"><button type="button" class="text-left text-base font-medium" aria-pressed="'+!!q.selected+'"'+actAttrs(q.act,q.args)+'>'+h(x.canonicalName)+'</button><p class="mt-2 text-compact text-cafe-muted">'+(x.status==='retired'?tc("v2f.copy.w038"):tc("v2f.copy.w039"))+(x.aliases.length?' · '+h(x.aliases.join('、')):'')+'</p></article>';};
PDL_COMPONENTS.v2MemoryEventCard=function(p,sc,root){const q=pvDeep(p,root,sc),x=q.record;return '<article class="rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-4"><button type="button" class="text-left text-base font-medium" aria-pressed="'+!!q.selected+'"'+actAttrs(q.act,q.args)+'>'+h(x.type)+'</button><p class="mt-2 line-clamp-3 break-words text-compact text-cafe-muted">'+h(x.summary)+'</p><p class="mt-2 text-xs text-cafe-muted">'+h(v2MemoryDate(x.timestamp))+(x.summaryTruncated?" "+tc("v2f.copy.w040"):'')+(x.pendingCorrectionCount>0?' · '+x.pendingCorrectionCount+" "+tc("v2f.copy.w030"):'')+'</p></article>';};
PDL_COMPONENTS.v2MemoryLibrary=function(p,sc,root){const x=pv(p.data,sc,root);return ("<section aria-label=\""+h(tc("v2f.copy.w041"))+"\" class=\"space-y-5\"><header class=\"flex flex-wrap items-start justify-between gap-3\"><div><h1 class=\"text-display-sm font-medium\">"+h(tc("v2f.copy.w041"))+"</h1><p class=\"mt-2 text-sm text-cafe-muted\">"+h(tc("v2f.copy.w042"))+"</p></div><button type=\"button\" class=\"rounded-lg border border-cafe-subtle px-3 py-2 text-compact\"")+actAttrs('modal',{v:'lib'})+(">"+h(tc("v2f.copy.w044"))+"</button></header><div class=\"grid items-start gap-6 xl:grid-cols-3\"><div class=\"min-w-0 space-y-6 xl:col-span-2\"><section aria-label=\""+h(tc("v2f.copy.w043"))+"\">")+pvBlocks(p.blocks,sc,root)+("</section><section aria-label=\""+h(tc("v2f.copy.w045"))+"\"><div class=\"mb-3 flex flex-wrap items-center justify-between gap-3\"><h2 class=\"text-base font-medium\">"+h(tc("v2f.copy.w045"))+" "+"<span class=\"ml-2 text-cafe-muted\">")+h(x.collectionCount)+(" "+h(tc("v2f.copy.w046"))+"</span></h2><button class=\"text-compact text-cafe-accent underline\"")+actAttrs('set',{path:'cs.m.lib',v:'collections'})+(">"+h(tc("v2f.copy.w047"))+"</button></div><div class=\"rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] px-4\"><div class=\"hidden grid-cols-5 gap-3 border-b border-cafe-subtle py-3 text-compact text-cafe-muted md:grid\"><span class=\"col-span-2\">"+h(tc("v2f.copy.w048"))+"</span><span>"+h(tc("v2f.copy.w049"))+"</span><span>"+h(tc("v2f.copy.w050"))+"</span><span>"+h(tc("v2f.copy.w051"))+"</span></div>")+x.colls.map(function(c){return '<div class="grid gap-2 border-b border-cafe-subtle py-4 last:border-0 md:grid-cols-5 md:gap-3"><div class="min-w-0 md:col-span-2"><p class="break-words text-sm font-medium">'+h(c.name)+'</p></div><p class="text-compact text-cafe-secondary">'+h(c.type)+' · '+h(c.vis)+'</p><p class="text-compact text-cafe-secondary">'+h(c.docs)+(" "+h(tc("v2f.copy.w052"))+"</p><p class=\"text-compact text-cafe-muted\">")+h(c.upd)+'</p></div>';}).join('')+("</div></section></div><aside class=\"h-fit rounded-xl border border-cafe-subtle bg-[var(--console-card-bg)] p-5\" aria-label=\""+h(tc("v2f.copy.w053"))+"\">")+PDL_COMPONENTS.v2MemoryStatusLine({data:{lit:{evidence:x.evidence,maintenance:x.maintenance}}},sc,root)+("<dl class=\"mt-4 grid grid-cols-2 gap-2 text-compact text-cafe-secondary\"><dt>"+h(tc("v2f.copy.w050"))+"</dt><dd>")+h(x.evidence.docs_count)+(" "+h(tc("v2f.copy.w052"))+"</dd><dt>"+h(tc("v2f.copy.w054"))+"</dt><dd>")+h(x.evidence.passages_count)+(" "+h(tc("v2f.copy.w046"))+"</dd><dt>"+h(tc("v2f.copy.w055"))+"</dt><dd>")+h(x.evidence.edges_count)+(" "+h(tc("v2f.copy.w010"))+"</dd></dl></aside></div></section>");};
/* memory/MemoryHub.tsx — catalog is the original separate page, including its outer surface. */
PDL_COMPONENTS.v2CatalogHeading=function(p,sc,root){return '<div class="flex items-center justify-between mb-3"><span class="text-xs text-cafe-secondary">'+pvText(p.count,sc,root)+(" "+h(tc("v2f.copy.w057"))+"</span>")+pvBlocks(p.actions,sc,root)+'</div>';};
PDL_COMPONENTS.v2CollectionDocumentGroup=function(p,sc,root){const x=pv(p.record,sc,root);return '<div><div class="flex items-center gap-1.5 mb-1"><span class="text-xs font-medium text-cafe-primary capitalize">'+h(x.title)+'</span><span class="text-micro text-cafe-secondary">('+h(x.count)+')</span></div><ul class="space-y-0.5 pl-3">'+x.items.map(function(d){return '<li class="text-xs text-cafe-secondary flex items-baseline gap-1.5"><button class="truncate"'+actAttrs('recallSource',{anchor:d.anchor,collection:d.collection})+'>'+h(d.title||d.anchor)+'</button>'+(d.updatedAt?'<span class="text-micro text-cafe-tertiary shrink-0">'+h(d.updatedAt.slice(0,10))+'</span>':'')+'</li>';}).join('')+'</ul></div>';};

/* settings/SettingsShellV2.tsx and SettingsSecondLevel.tsx. */
PDL_COMPONENTS.v2SettingsNav=function(p,sc,root){const q=pvDeep(p,root,sc),me=q.owner;return '<aside class="v2-settings-sidebar flex max-h-[42vh] w-full flex-shrink-0 flex-col overflow-hidden md:max-h-none" style="background:var(--shell-frame);border-right:1px solid var(--shell-hairline)" data-console-panel="settings-nav" data-okey="nav"><div class="flex items-center justify-between gap-3 px-4 pb-2 pt-2 md:pt-4"><h1 class="m-0 text-sm font-semibold" style="color:var(--shell-ink)">'+h(tc('v2.settings'))+'</h1></div><nav id="settings-mobile-navigation" aria-label="'+h(tc('v2.settings'))+'" class="min-h-0 flex-1 overflow-y-auto px-2 pb-4">'+q.groups.map(function(g){const id=g.items[0],active=g.items.some(pdlCur)||(g.routes||[]).indexOf(S.route)>=0;return (g.divider?'<div aria-hidden="true" class="mx-2 my-1.5 h-px" style="background:var(--shell-hairline)"></div>':'')+'<div class="v2-settings-nav-item relative flex items-center"><button type="button" class="shell-nav-row shell-focusable flex h-9 w-full items-center gap-2.5 rounded-lg px-2.5 text-left text-sm" data-act="open" data-ref="'+h(id)+'" data-from="'+h(q.slot)+'" data-active="'+active+'"'+(active?' aria-current="page" data-selected="true"':'')+' style="color:var(--shell-'+(active?'ink':'body')+');'+(active?'background:var(--shell-selected);font-weight:500':'')+'">'+(g.id==='you'?v2Avatar({kind:'user',name:me.name},20,me.avatar,me.name)+'<span class="min-w-0 truncate">'+h(me.name)+'</span><span style="color:var(--shell-muted)">'+h(g.title)+'</span>':'<span class="flex-none" style="color:var(--shell-muted)">'+v2HubGlyph(g.icon)+'</span><span class="min-w-0 flex-1 truncate">'+h(g.title)+'</span>')+'</button><span class="v2-settings-pin absolute right-1 opacity-0"><button type="button" class="h-6 w-6 flex items-center justify-center rounded"'+actAttrs('rail',{k:id})+' aria-label="'+h(tc('frame.pinRail'))+'">'+v2Glyph('pin','h-3 w-3')+'</button></span></div>';}).join('')+'</nav></aside>';};
PDL_COMPONENTS.v2SettingsTabs=function(p,sc,root){const q=pvDeep(p,root,sc),g=q.groups.find(function(g){return g.items.some(pdlCur)||(g.routes||[]).indexOf(S.route)>=0;});if(!g||g.items.length<2)return '';return '<div class="flex shrink-0 items-start justify-between gap-2"><div role="tablist" aria-label="'+h(g.title)+'" class="flex min-w-0 flex-1 flex-wrap items-center gap-1">'+g.items.map(function(id){const selected=pdlCur(id);return '<button type="button" role="tab" id="settings-tab-'+h(id)+'" aria-controls="settings-tabpanel" class="shell-nav-row shell-focusable h-8 rounded-lg px-3 text-sm" aria-selected="'+selected+'"'+(selected?' data-selected="true"':'')+' data-act="open" data-ref="'+h(id)+'" data-from="'+h(q.slot)+'" style="color:var(--shell-'+(selected?'ink':'body')+');'+(selected?'background:var(--shell-selected);font-weight:500':'')+'">'+h(q.labels[id])+'</button>';}).join('')+'</div><div class="flex h-8 shrink-0 items-center gap-1"><button class="h-6 w-6 flex items-center justify-center rounded"'+actAttrs('rail',{k:g.items.find(pdlCur)||g.items[0]})+' aria-label="'+h(tc('frame.pinRail'))+'">'+v2Glyph('pin','h-3 w-3')+'</button></div></div>';};
PDL_COMPONENTS.v2SettingsPage=function(p,sc,root){const blocks=p.blocks||[],body=p.panel?pvBlocks(blocks.slice(0,1),sc,root)+'<div role="tabpanel" id="settings-tabpanel" class="'+(p.fixed?'flex min-h-0 flex-1 flex-col gap-5 overflow-hidden':'space-y-5')+' outline-none">'+pvBlocks(blocks.slice(1),sc,root)+'</div>':pvBlocks(blocks,sc,root);return '<div class="v2-settings-content min-h-0 min-w-0 flex-1 '+(p.fixed?'flex flex-col overflow-hidden':'overflow-y-auto')+'" data-background-sampling-area="settings-content"><div class="'+(p.fixed?'flex h-full min-h-0 flex-col gap-5':'space-y-5')+' px-5 py-5 md:px-8 md:py-7">'+body+'</div></div>';};
/* members/MemberListPage.tsx. */
