PDL_COMPONENTS.v2MemberDefaultCat=function(p,sc,root){const q=pvDeep(p,root,sc);return ("<div class=\"member-default-control\"><span class=\"inline-flex items-center gap-2\"><label for=\"um-default\"><strong>"+h(tc("v2f.copy.w065"))+("</strong></label><span class=\"v2-help\" data-tip=\""+h(tc("v2f.defaultCatHelp"))+"\">?</span></span><select id=\"um-default\" data-change=\""))+h(q.change)+("\" aria-label=\""+h(tc("v2f.copy.w065"))+"\">")+q.options.map(function(x){return '<option value="'+h(x.id)+'"'+(q.value===x.id?' selected':'')+'>'+h(x.name)+' · '+h(x.model)+'</option>';}).join('')+'</select></div>';};
