/* ConfirmDialog.tsx. The existing popup engine owns the backdrop and dismissal. */
function dialogHtml(d){
 const drawing=d.body&&typeof d.body==='object'&&pdlLoc(PDL_VIEWS[d.body.id]),block=drawing&&drawing.blocks&&drawing.blocks[0],component=block&&block.type==='component'&&PDL_COMPONENTS[block.use];
 if(component&&component.dialog)return '<div class="dialog" data-v2-dialog style="display:contents">'+component(block.props,d,d)+'</div>';
 const key=d.key||'dialog',form=d.form||(!d.key&&d.ok?'dialog':''),tag=form?'form':'section',tid='v2-dialog-'+key,body=typeof d.body==='object'?pvBlocks([d.body],d,d):d.body||'';
 const close='<button type="button" class="v2-dialog-close flex h-[26px] w-[26px] items-center justify-center rounded-lg text-cafe-muted hover:bg-[var(--console-hover-bg)]"'+actAttrs('close',{popup:key})+' aria-label="'+h(tc('common.close'))+'">'+v2Glyph('close')+'</button>';
 return '<'+tag+' class="dialog v2-confirm-dialog bg-cafe-surface rounded-xl shadow-xl p-6 max-w-sm w-full mx-4'+(d.wide?' v2-dialog-wide':'')+(d.layout?' v2-dialog-'+h(d.layout):'')+(d.span==='full'?' v2-dialog-full':'')+'" role="'+(d.alert?'alertdialog':'dialog')+'"'+(d.modal===false?'':' aria-modal="true"')+' aria-labelledby="'+h(tid)+'"'+(form?' data-form="'+h(form)+'"':'')+'><header class="mb-2 flex items-center gap-2"><h3 id="'+h(tid)+'" class="min-w-0 flex-1 text-base font-semibold">'+h(d.title)+'</h3>'+(d.help?'<span class="v2-help" data-tip="'+h(d.help)+'">?</span>':'')+(d.actions||'')+(!d.ok?close:'')+'</header><div class="dialog-body v2-dialog-body">'+(d.panes?'<div class="mb-4 flex gap-1">'+d.panes.items.map(function(x){return '<button type="button" class="rounded-lg px-3 py-2 text-sm"'+actAttrs('set',{path:'s.dialog.panes.cur',v:x.v})+' aria-pressed="'+(x.v===d.panes.cur)+'">'+h(x.label)+'</button>';}).join('')+'</div>':'')+(d.text?'<p class="text-sm text-cafe-secondary mb-4 whitespace-pre-wrap">'+(typeof d.text==='string'?h(d.text):v2Part(d.text.parts,d.text.data,d.text.data))+'</p>':'')+(d.error?'<p role="alert" class="mb-4 text-sm text-conn-red-text">'+h(d.error)+'</p>':'')+(d.fields?d.fields.filter(function(f){return !f.pane||!d.panes||f.pane===d.panes.cur;}).map(dlgField).join(''):'')+(d.doc?docBody(d.doc):'')+body+'</div>'+(d.foot?'<div class="mt-4 text-xs text-cafe-muted">'+dlgFoot(d.foot)+'</div>':'')+(d.acts?'<div class="acts flex justify-end gap-2">'+v2DialogActions(d.acts)+'</div>':d.ok?'<div class="acts flex justify-end gap-2">'+(d.ack?'':'<button type="button" class="px-4 py-2 text-sm text-cafe-secondary hover:bg-cafe-surface-elevated rounded-lg transition-colors"'+actAttrs('close',{popup:key})+'>'+h(tc('common.cancel'))+'</button>')+'<button type="submit" class="px-4 py-2 text-sm text-[var(--cafe-surface)] rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed '+(d.danger?'bg-semantic-critical':'bg-semantic-info')+'">'+h(d.ok)+'</button></div>':'')+'</'+tag+'>';
}
function v2DialogActions(xs){if(typeof xs==='string')return xs;return xs.map(function(x){if(x[0]==='cancel'||x[0]==='done')return '<button class="px-4 py-2 text-sm text-cafe-secondary rounded-lg"'+actAttrs('close',{popup:x[1]})+'>'+h(x[0]==='cancel'?tc('common.cancel'):tc('common.done'))+'</button>';const p=x[1];return '<button type="'+(p.submit?'submit':'button')+'" class="px-4 py-2 text-sm rounded-lg '+(p.primary?'text-[var(--cafe-surface)] '+(p.danger?'bg-semantic-critical':'bg-semantic-info'):'text-cafe-secondary hover:bg-cafe-surface-elevated')+'"'+actAttrs(p.act,p.args)+(p.data||'')+(p.disabled?' disabled':'')+'>'+(p.icon?v2Glyph(p.icon):'')+h(x[0])+'</button>';}).join('');}
/* SettingsField / existing old native inputs. Additional hook attributes retain the form contract. */
function dlgField(f){
  if(f.kv)return '<dl class="grid grid-cols-2 gap-2 text-sm">'+f.kv.map(function(x){return '<dt class="text-cafe-muted">'+h(x[0])+'</dt><dd>'+h(x[1])+'</dd>';}).join('')+'</dl>';
  if(f.pre)return '<pre class="whitespace-pre-wrap break-words rounded-lg bg-[var(--console-field-bg)] p-3 text-xs">'+h(f.pre)+'</pre>';
  if(f.check)return '<label class="flex items-center gap-2 text-sm mb-4"><input type="checkbox" id="'+h(f.id)+'"'+(f.checked?' checked':'')+'>'+h(f.check)+'</label>';
  const cls='w-full border border-cafe rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--semantic-info)]',attrs=' id="'+h(f.id)+'"'+(f.disabled?' disabled':'')+(f.readonly?' readonly':'')+(f.placeholder?' placeholder="'+h(f.placeholder)+'"':'')+(f.change?' data-change="'+h(f.change)+'"':'')+(f.req?' required':'')+(f.max?' maxlength="'+f.max+'"':'');
  let input;
  if(f.options)input='<select class="'+cls+'"'+attrs+'>'+f.options.map(function(x){const o=Array.isArray(x)?{v:x[0],label:x[1]}:typeof x==='object'?x:{v:x,label:x};return '<option value="'+h(o.v)+'"'+(String(o.v)===String(f.value)?' selected':'')+'>'+h(o.label||o.title)+'</option>';}).join('')+'</select>';
  else if(f.area)input='<textarea class="'+cls+'"'+attrs+' rows="'+(f.rows||4)+'">'+h(f.value)+'</textarea>';
  else if(f.chips)input='<div class="flex flex-wrap gap-2" id="'+h(f.id)+'">'+f.chips.vals.map(function(x){return '<span class="rounded-full border border-cafe-subtle px-2 py-1 text-xs">'+h(x)+(f.chips.lock===x?'':'<button type="button"'+actAttrs('chipDel',{for:f.id,kind:f.chips.kind||'',k:'',v:x})+(" aria-label=\""+h(tc("v2f.copy.w116"))+"\">×</button>"))+'</span>';}).join('')+'<span class="ifield flex items-center gap-1" data-go="chipAdd" data-for="'+h(f.id)+'" data-kind="'+h(f.chips.kind||'')+'"><input id="'+h(f.id)+'-in" class="'+cls+'" placeholder="'+h(f.chips.ph)+'" data-on-enter="fieldGo"><button type="button"'+actAttrs('fieldGo',{})+(" aria-label=\""+h(tc("v2f.copy.w117"))+"\">")+v2Glyph('check')+'</button></span></div>';
  else if(f.color)input=PDL_COMPONENTS.v2Color({id:f.id,label:f.label,value:{lit:f.color.value}},f,f);
  else if(f.avatar)input='<div class="flex items-center gap-3">'+v2Avatar('me',48)+'<input type="file" accept="image/png,image/jpeg,image/webp"'+attrs+(" data-filemsg=\""+h(tc("v2f.copy.w118"))+"\"></div>");
  else if(f.radios)input='<div class="space-y-2">'+f.radios.map(function(x,i){return '<label class="flex items-center gap-2 text-sm"><input type="radio" name="'+h(f.id)+'" value="'+h(x.v)+'"'+((f.value!=null?f.value===x.v:i===0)?' checked':'')+'><span>'+h(x.title)+(x.sub?'<small class="block text-cafe-muted">'+h(x.sub)+'</small>':'')+'</span></label>';}).join('')+'</div>';
  else if(f.opts)input='<div class="space-y-2">'+f.opts.items.map(function(x){return '<button type="button" class="w-full rounded-lg border border-cafe-subtle p-3 text-left text-sm"'+actAttrs('set',{path:'dlgf.'+f.id+'.opts.cur',v:x.v})+' aria-pressed="'+(x.v===f.opts.cur)+'">'+h(x.title)+(x.sub?'<small class="mt-1 block text-xs text-cafe-muted">'+h(x.sub)+'</small>':'')+'</button>';}).join('')+(f.opts.custom&&f.opts.cur==='custom'?'<input class="'+cls+'" id="'+h(f.opts.custom.id)+'" value="'+h(f.opts.custom.value)+'" placeholder="'+h(f.opts.custom.placeholder)+'">':'')+'</div>';
  else if(f.env)input='<button type="button" class="text-xs text-cafe-accent"'+actAttrs('toggle',{path:'dlgf.'+f.id+'.env.open'})+'>'+h(f.env.toggle||tc("v2f.copy.w119"))+'</button>'+(f.env.open?'<div class="space-y-2">'+f.env.rows.map(function(r,i){return '<div class="grid grid-cols-2 gap-2"><input id="'+h(f.id)+'-k'+i+'" class="'+cls+'" value="'+h(r[0])+("\" placeholder=\""+h(tc("v2f.copy.w120"))+"\"><input id=\"")+h(f.id)+'-v'+i+'" class="'+cls+'" value="'+h(r[1])+("\" placeholder=\""+h(tc("v2f.copy.w121"))+"\"></div>");}).join('')+'<button type="button" class="text-xs text-cafe-accent"'+actAttrs('listOp',{path:'dlgf.'+f.id+'.env.rows',op:'add',shape:'pair'})+(">"+h(tc("v2f.copy.w117"))+"</button></div>"):'');
  else if(f.swatch)input='<div class="flex gap-2" data-swatch="'+h(f.id)+'">'+[1,2,3,4,5,6].map(function(n){return '<button type="button" role="radio" aria-checked="'+(f.swatch.cur===n)+'" class="h-6 w-6 rounded-full border border-cafe-subtle" style="background:var(--tint-'+n+')"'+actAttrs('swatch',{n:n,v:n})+(" aria-label=\""+h(tc("v2f.colorPrefix"))+" ")+n+'"></button>';}).join('')+'</div>';
  else input='<input class="'+cls+'" type="'+(f.file?'file':f.type||'text')+'"'+attrs+(f.file?(f.file.accept?' accept="'+h(f.file.accept)+'"':'')+(f.file.change?' data-change="'+h(f.file.change)+'"':''):' value="'+h(f.value)+'"')+(f.min!=null?' min="'+f.min+'"':'')+(f.maxv!=null?' max="'+f.maxv+'"':'')+'>';
  return '<div class="space-y-1.5 mb-4">'+(f.label?'<div class="flex items-center gap-2"><label class="text-sm font-medium text-cafe" for="'+h(f.id)+'">'+h(f.label)+'</label>'+(f.help?'<span class="v2-help" data-tip="'+h(f.help)+'">?</span>':'')+'</div>':'')+'<div>'+input+'</div>'+((f.foot||f.links)?'<p class="mt-1 text-xs text-cafe-muted">'+dlgFootHtml(f)+'</p>':'')+'</div>';
}
function docBody(d){return '<div class="space-y-3">'+(d.meta!=null?'<p class="text-xs text-cafe-muted"'+(d.metaId?' id="'+h(d.metaId)+'"':'')+'>'+h(d.path)+' '+h(d.meta)+'</p>':'')+(d.segs||[]).map(function(g){return '<div class="flex flex-wrap items-center gap-2">'+(g.label?'<span class="text-xs text-cafe-muted">'+h(g.label)+'</span>':'')+PDL_COMPONENTS.v2Segments({from:g.items,act:g.act,args:g.args},d,d)+'</div>';}).join('')+(d.edit?'<textarea class="w-full rounded-lg border border-cafe-subtle p-3 text-xs font-mono" id="'+h(d.id)+'" rows="'+(d.rows||16)+'"'+(d.readonly?' readonly':'')+'>'+h(d.text)+'</textarea>':'<pre class="overflow-auto whitespace-pre-wrap rounded-lg bg-[var(--console-field-bg)] p-3 text-xs"'+(d.id?' id="'+h(d.id)+'"':'')+'>'+h(d.text)+'</pre>')+'<div class="flex flex-wrap gap-2">'+(d.acts||[]).map(function(a){return PDL_COMPONENTS.v2Action(a,d,d);}).join('')+'</div></div>';}
PDL_COMPONENTS.v2Dialog=function(p,sc,root){const q=pvDeep({key:p.pop,form:p.form,title:p.title,wide:p.wide,error:p.error,layout:p.layout,span:p.span,help:p.help},root,sc);return dialogHtml(Object.assign(q,{actions:v2Controls(p.actions,sc,root),body:pvBlocks(p.blocks,sc,root),acts:pvBlocks(p.footer,sc,root)}));};
/* ToastContainer.tsx / ToastCard. Its lifetime remains owned by the existing engine. */
function toastHtml(t,a,o){o=o||{};return '<div class="toast v2-toast bg-cafe-surface rounded-lg shadow-lg border border-cafe-subtle border-l-4 px-3 py-2.5 max-h-[70vh] max-w-xs overflow-y-auto pointer-events-auto" role="alert"'+(o.attrs||'')+("><div class=\"flex items-start gap-2\"><span class=\"text-sm flex-shrink-0 mt-0.5\">"+h(tc("v2f.copy.w001"))+"</span><div data-testid=\"toast-content\" class=\"min-w-0 flex-1\"><p class=\"break-words text-sm font-medium leading-5 text-cafe\">")+h(t)+'</p>'+[].concat(a||[]).map(function(x){return '<button type="button" class="mt-1.5 rounded-md border border-cafe px-2 py-1 text-xs font-semibold text-cafe-interactive hover:bg-cafe-surface-sunken"'+actAttrs(x.act,typeof x.data==='object'?x.data:{})+(typeof x.data==='string'?x.data:'')+'>'+h(x.label)+'</button>';}).join('')+'</div></div></div>';}

/* mission-control/MissionControlPage.tsx. */
