PDL_COMPONENTS.v2MissionSummary=function(p,sc,root){const q=pv(p.counts,sc,root);return '<div class="flex flex-wrap items-center gap-5 console-divider-b py-2.5">'+[['suggested',tc("v2f.copy.w123")],['dispatched',tc("v2f.copy.w124")],['done',tc("v2f.copy.w125")]].map(function(x){return '<span class="flex items-center gap-1.5"><span class="h-2 w-2 rounded-full" style="background:var(--mc-status-'+x[0]+'-dot)"></span><span class="text-xs font-medium" style="color:var(--mc-status-'+x[0]+'-text)">'+h(q[x[0]])+' '+x[1]+'</span></span>';}).join('')+'</div>';};
