PDL_COMPONENTS.v2QuickCreateForm=function(p,sc,root){const q=pvDeep(p,root,sc),cls='w-full rounded-[10px] border-transparent bg-[var(--console-field-bg,var(--console-card-bg))] px-2 py-1.5 text-xs text-cafe outline-none focus:ring-1 focus:ring-cafe-accent';return ("<form class=\"grid grid-cols-12 gap-2 rounded-xl bg-[var(--console-card-bg)] p-3 shadow-[0_8px_22px_rgba(43,33,26,0.04)]\"><label class=\"col-span-3\"><input id=\"dlg-tt\" placeholder=\""+h(tc("v2f.copy.w126"))+"\" class=\"")+cls+("\"></label><label class=\"col-span-4\"><input id=\"dlg-s\" placeholder=\""+h(tc("v2f.copy.w127"))+"\" class=\"")+cls+'"></label><label class="col-span-1"><select id="dlg-p" class="'+cls+("\"><option>"+h(tc("v2f.copy.w129"))+"</option><option>"+h(tc("v2f.copy.w130"))+"</option><option selected>"+h(tc("v2f.copy.w131"))+"</option><option>"+h(tc("v2f.copy.w132"))+"</option></select></label><label class=\"col-span-3\"><input id=\"dlg-g\" placeholder=\""+h(tc("v2f.copy.w128"))+"\" class=\"")+cls+'"></label><button type="button" class="col-span-1 rounded-lg bg-cafe-accent px-2 py-1.5 text-xs font-semibold text-[var(--cafe-surface)]"'+actAttrs(q.act,q.args)+(">"+h(tc("v2f.copy.w133"))+"</button></form>");};
/* FeatureRowList: features in id order, Untagged last */
